using KansoDesktop;
int passed=0;
void Check(bool condition,string message){if(!condition)throw new Exception(message);Console.WriteLine("PASS "+message);passed++;}
var root=Path.Combine(Path.GetTempPath(),"kanso-reference-checks-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
var desktop=Directory.CreateDirectory(Path.Combine(root,"OneDrive","Desktop")).FullName;
var folder=Directory.CreateDirectory(Path.Combine(desktop,"OriginalFolder")).FullName;
var file=Path.Combine(folder,"keep.txt");File.WriteAllText(file,"original content");
var a=new FenceModel();var b=new FenceModel();var state=new Settings {Fences=new(){a,b}};
state.Assign(folder,a);state.Assign(folder.ToUpperInvariant(),b);
Check(a.Paths.Count==0&&b.Paths.Count==1,"Assignments remain exclusive, ignoring Windows path case");
Check(Directory.Exists(folder)&&File.ReadAllText(file)=="original content","Grouping never moves or changes an original OneDrive folder");
Check(!Directory.Exists(Path.Combine(root,"Groups")),"No managed storage directory is created by assignment");
b.Paths.Clear();Check(File.Exists(file),"Ungrouping leaves original files in place");
var offline=Path.Combine(desktop,"Offline.txt");state.Assign(offline,a);
var items=DesktopInventory.Read(new[]{desktop},a.Paths.ToArray());
Check(items.Any(i=>i.Path==folder&&i.Folder)&&items.Any(i=>i.Path==offline&&i.Missing),"Inventory retains temporarily unavailable assigned items");
Check(File.ReadAllText(file)=="original content","Inventory reads do not alter contents");
var originalAttributes=File.GetAttributes(folder);File.SetAttributes(folder,originalAttributes|FileAttributes.ReadOnly);
state.Assign(folder,a);Check(File.GetAttributes(folder).HasFlag(FileAttributes.ReadOnly),"Grouping leaves folder attributes untouched");
a.Width=-1;a.X=-1080;state.PanelOpacity=double.NaN;state.Normalize();
Check(a.Width==240&&a.X==-1080&&state.PanelOpacity==.55,"Geometry sanitization preserves negative monitor coordinates");
var store=new LayoutStore(Path.Combine(root,"layout.json"));store.Save(state);var round=store.Load();store.Save(round);
Check(round.Fences[0].Paths.Count==2&&File.Exists(store.FileName+".bak"),"Atomic layout round trip retains paths and backup");
File.WriteAllText(store.FileName,"{broken");bool invalid=false;try{store.Load();}catch{invalid=true;}
Check(invalid&&File.ReadAllText(store.FileName)=="{broken","Corrupt layout fails without overwriting it");
var single=new SingleFlight<int>();using var release=new ManualResetEventSlim();int workers=0;
var watch=System.Diagnostics.Stopwatch.StartNew();bool timedOut=false;
try{await single.RunAsync(()=>{Interlocked.Increment(ref workers);release.Wait();return 7;},TimeSpan.FromMilliseconds(60));}catch(TimeoutException){timedOut=true;}
Check(timedOut&&watch.ElapsedMilliseconds<1500,"Blocked I/O times out for the caller");
await single.RunAsync(()=>{Interlocked.Increment(ref workers);return 9;},TimeSpan.FromMilliseconds(60));
Check(single.Busy&&workers==1,"Timed-out operation cannot spawn overlapping workers");
release.Set();for(int i=0;i<100&&single.Busy;i++)await Task.Delay(10);
Check(await single.RunAsync(()=>9,TimeSpan.FromSeconds(1))==9,"Slot recovers once the delayed operation finishes");
Check(Themes.All.Length==4,"Four built-in themes preserved");
Console.WriteLine($"{passed} checks passed. Only artificial data used.");
var screenBounds=new System.Drawing.Rectangle(-1080,-344,1080,1920);
var sparse=IconLayout.Arrange(screenBounds,screenBounds,false,new[]{new IconPoint("a",-900,100),new IconPoint("b",-800,250)});
Check(sparse.Bounds.Width==176&&sparse.Bounds.Height==250,"Sparse icons allocate a tight surface and preserve negative monitor coordinates");
Check(sparse.Items[0].X==-900&&sparse.Items[1].Y==250,"Saved physical icon positions are preserved");
var empty=IconLayout.Arrange(screenBounds,screenBounds,false,Array.Empty<IconPoint>());
Check(empty.Bounds.Width==1&&empty.Bounds.Height==1&&empty.Items.Count==0,"Empty monitors do not allocate full-screen transparent bitmaps");
var primaryBounds=new System.Drawing.Rectangle(0,0,1920,1080);
var fresh=IconLayout.Arrange(primaryBounds,primaryBounds,true,new[]{new IconPoint("old",12,12),new IconPoint("new",int.MinValue,int.MinValue)});
Check(fresh.Items.Count==2&&fresh.Items[1].Y>=112,"New icon fallback avoids occupied cells");
var other=IconLayout.Arrange(screenBounds,screenBounds,false,new[]{new IconPoint("new",int.MinValue,int.MinValue)});
Check(other.Items.Count==0,"Fallback icons are not duplicated across monitors");
bool full=false;try{IconLayout.Arrange(new(0,0,50,50),new(0,0,50,50),true,new[]{new IconPoint("new",int.MinValue,int.MinValue)});}catch(InvalidOperationException){full=true;}
Check(full,"Insufficient icon space fails visibly instead of dropping icons offscreen");
Console.WriteLine($"{passed} checks passed.");
var fold=new FoldBehavior(true,false);Check(fold.Folded,"Automatic mode starts as a title tab");
fold.Enter();Check(!fold.Folded,"Hover opens the group");fold.Leave();fold.Interaction(true);fold.Expire();Check(!fold.Folded,"Active drag prevents automatic collapse");
fold.Interaction(false);fold.Menu(true);fold.Expire();Check(!fold.Folded,"Context menus prevent automatic collapse");fold.Menu(false);fold.Expire();Check(fold.Folded,"Group collapses after context menu closes outside it");
fold.Enter();fold.Toggle();fold.Enter();Check(fold.Folded,"Manual collapse is not undone by duplicate enter events");fold.Leave();fold.Enter();Check(!fold.Folded,"A new hover opens a manually collapsed tab");
fold.Leave();fold.SetAuto(false);fold.Expire();Check(!fold.Folded,"Disabling automatic collapse leaves the group open");
var savedPos=GroupPlacement.Reachable(-900,100,380,new[]{screenBounds,primaryBounds},primaryBounds);
Check(savedPos.X==-900&&savedPos.Y==100,"Reachable negative group positions survive monitor validation");
var detached=GroupPlacement.Reachable(6000,-4000,380,new[]{primaryBounds},primaryBounds);
Check(detached.X>=0&&detached.Y>=0&&detached.X<1920,"Detached-monitor group returns to reachable desktop area");
var mostlyOff=GroupPlacement.Reachable(1910,20,380,new[]{primaryBounds},primaryBounds);
Check(mostlyOff.X!=1910,"A tiny visible fragment does not strand the draggable title");
var palette=new Settings{Accent="invalid",Panel="transparent"};palette.Normalize();Check(palette.Accent=="#DFA0B6"&&palette.Panel=="#17141D","Invalid imported colors fall back without crashing views");
state.DesktopPositions[folder]=new DesktopPoint(-900,100);var positionalStore=new LayoutStore(Path.Combine(root,"positions.json"));positionalStore.Save(state);
var positionsRound=positionalStore.Load();Check(positionsRound.DesktopPositions[folder.ToUpperInvariant()].X==-900,"Loose icon positions round-trip with case-insensitive paths");
Console.WriteLine($"{passed} checks passed.");
using(var writeStarted=new ManualResetEventSlim())using(var unblockWrite=new ManualResetEventSlim()){
 var written=new System.Collections.Concurrent.ConcurrentQueue<string>();int writes=0;
 var queue=new LatestWriteQueue(payload=>{if(Interlocked.Increment(ref writes)==1){writeStarted.Set();unblockWrite.Wait();}written.Enqueue(payload);});
 queue.Request("first");Check(writeStarted.Wait(2000),"Writer starts on its background worker");
 for(int i=0;i<100;i++)queue.Request("latest-"+i);
 Check(queue.PendingCount==1,"Repeated saves coalesce to one pending snapshot");unblockWrite.Set();await queue.Completion.WaitAsync(TimeSpan.FromSeconds(3));
 Check(written.ToArray().SequenceEqual(new[]{"first","latest-99"}),"Only the initial and latest queued snapshots are written in order");
}
int failures=0;var retryQueue=new LatestWriteQueue(payload=>{if(Interlocked.Increment(ref failures)==1)throw new IOException("injected write failure");});
retryQueue.Request("old");bool saveFailed=false;try{await retryQueue.Completion;}catch(IOException){saveFailed=true;}
Check(saveFailed&&retryQueue.PendingCount==1,"Persistence errors are observable and retain a pending snapshot");
retryQueue.Request("new");await retryQueue.Completion;Check(retryQueue.Written==2,"A later save can recover from a failed write");
bool tooMany=false;try{new Settings{Fences=Enumerable.Range(0,257).Select(_=>new FenceModel()).ToList()}.Normalize();}catch(InvalidDataException){tooMany=true;}
Check(tooMany,"Oversized group imports fail before constructing thousands of windows");
Console.WriteLine($"{passed} checks passed.");
var manyGroup=new FenceModel();var manyState=new Settings{Fences=new(){manyGroup,new FenceModel()}};
var manyPaths=Enumerable.Range(0,5000).Select(i=>Path.Combine(desktop,"entry-"+i+".txt")).ToArray();
var batchWatch=System.Diagnostics.Stopwatch.StartNew();int batchCount=ReferenceAssignment.Apply(manyState,manyPaths,manyGroup);batchWatch.Stop();
Check(batchCount==5000&&manyGroup.Paths.Count==5000&&batchWatch.ElapsedMilliseconds<2000,"Large reference batches avoid quadratic UI work");
Check(ReferenceAssignment.Apply(manyState,manyPaths,manyGroup)==0,"Repeated assignment to the same group is a no-op");
var moved=ReferenceAssignment.Apply(manyState,manyPaths.Take(1000),manyState.Fences[1]);
Check(moved==1000&&manyGroup.Paths.Count==4000&&manyState.Fences[1].Paths.Count==1000,"Batch reassignment stays exclusive");
int beforeInvalid=manyGroup.Paths.Count;bool invalidGroup=false;try{ReferenceAssignment.Apply(manyState,new[]{folder},new FenceModel());}catch(InvalidOperationException){invalidGroup=true;}
Check(invalidGroup&&manyGroup.Paths.Count==beforeInvalid,"Stale menu targets cannot silently lose group ownership");
Check(ReferenceAssignment.Apply(manyState,new[]{"",null!,"shell:RecycleBinFolder"},manyGroup)==0,"Empty and virtual drops do not corrupt assignments");
Check(!Directory.EnumerateFileSystemEntries(desktop).Any(p=>Path.GetFileName(p).StartsWith("entry-")),"Large assignment batches create no original files or links");
Console.WriteLine($"{passed} checks passed.");
var workArea = new System.Drawing.Rectangle(-1920, -200, 1920, 1040);
var topDock = GroupPlacement.FoldBounds(-170, 330, workArea, 1, true);
Check(topDock.HeaderY == -188 && !topDock.Up && topDock.Height == 330, "Top docking keeps twelve-pixel gap on negative-origin monitor");
var bottomDock = GroupPlacement.FoldBounds(760, 330, workArea, 1, true);
Check(bottomDock.HeaderY == 776 && bottomDock.Up && bottomDock.Height == 330, "Bottom docking opens upward above taskbar work area");
var overflow = GroupPlacement.FoldBounds(650, 400, workArea, 1, false);
Check(overflow.Up && overflow.HeaderY == 650 && overflow.Height == 400, "Undocked group that would cross taskbar opens upward");
var scaled = GroupPlacement.FoldBounds(720, 400, workArea, 1.5, true);
Check(scaled.Up && scaled.HeaderY == 744 && scaled.Height == 400, "Docking scales title and gap at 150 percent DPI");
var tall = GroupPlacement.FoldBounds(100, 1800, workArea, 1, false);
Check(tall.Height < 1800 && tall.HeaderY + tall.Height <= workArea.Bottom - 12, "Oversized group remains inside usable screen and can scroll");
Console.WriteLine($"{passed} checks passed.");
var expandedBottom = GroupPlacement.SnapHeader(498, 330, false, workArea, 1);
Check(expandedBottom == 776, "Expanded bottom edge docks even when title is far from bottom");
var expandedTop = GroupPlacement.SnapHeader(90, 330, true, workArea, 1);
Check(expandedTop == -188, "Upward window top edge docks using visible frame");
Check(GroupPlacement.SnapHeader(100, 330, false, workArea, 1) == 100, "Dragging in monitor interior does not snap");
Check(GroupPlacement.SnapHeader(327, 330, false, workArea, 1.5) == 744, "Visible bottom edge snaps at mixed DPI");
Console.WriteLine($"{passed} checks passed.");
